<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; font-family: Arial, Helvetica, sans-serif; }
  button, textarea { font: inherit; }

  #desktop {
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    color: #f7f5f8;
    background:
      radial-gradient(circle at 72% 18%, rgba(244, 102, 53, .74) 0, rgba(244, 102, 53, .2) 18%, transparent 42%),
      radial-gradient(ellipse at 22% 86%, rgba(112, 42, 143, .93) 0, transparent 47%),
      linear-gradient(135deg, #241139 0%, #4a1651 42%, #b64044 69%, #ed702b 100%);
    position: relative;
  }

  #desktop::before {
    content: "";
    position: absolute;
    inset: 0;
    opacity: .24;
    background: linear-gradient(115deg, transparent 26%, rgba(255,255,255,.22) 26.2%, transparent 40%),
                linear-gradient(295deg, transparent 45%, rgba(31,13,48,.6) 45.2%, transparent 64%);
    pointer-events: none;
  }

  .topbar {
    position: absolute;
    z-index: 10;
    top: 0; left: 0; right: 0;
    height: 35px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 14px;
    background: rgba(20, 17, 25, .88);
    box-shadow: 0 1px 5px rgba(0,0,0,.45);
    font-size: 13px;
  }
  .topbar strong { font-weight: 600; }
  .topbar .status { color: #ddd6df; letter-spacing: .4px; }

  .desktop-icons {
    position: absolute;
    top: 56px;
    left: 18px;
    display: grid;
    gap: 18px;
    z-index: 1;
  }
  .desktop-icon {
    width: 82px;
    text-align: center;
    font-size: 13px;
    text-shadow: 0 1px 3px #111;
  }
  .desktop-icon .icon-art {
    display: block;
    font-size: 43px;
    line-height: 48px;
    filter: drop-shadow(0 3px 2px rgba(0,0,0,.3));
  }

  #taskbar {
    position: absolute;
    z-index: 20;
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 8px 10px;
    border: 1px solid rgba(255,255,255,.19);
    border-radius: 18px;
    background: rgba(29, 25, 35, .76);
    backdrop-filter: blur(13px);
    box-shadow: 0 8px 28px rgba(0,0,0,.42);
  }
  .launcher {
    border: 0;
    min-width: 57px;
    height: 51px;
    padding: 4px 8px;
    color: white;
    background: transparent;
    border-radius: 11px;
    cursor: pointer;
    transition: background .15s, transform .15s;
  }
  .launcher:hover { background: rgba(255,255,255,.16); transform: translateY(-2px); }
  .launcher .launcher-icon { display: block; font-size: 27px; line-height: 29px; }
  .launcher small { display: block; font-size: 10px; color: #eee; }

  .window {
    position: absolute;
    z-index: 5;
    display: none;
    min-width: 360px;
    min-height: 240px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,.25);
    border-radius: 11px;
    background: #29272d;
    box-shadow: 0 18px 45px rgba(0,0,0,.52);
  }
  .window.visible { display: flex; flex-direction: column; }
  #files-window { width: 650px; height: 455px; top: 84px; left: 145px; }
  #notepad-window { width: 590px; height: 430px; top: 122px; left: 310px; }

  .titlebar {
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-left: 15px;
    background: #37343b;
    border-bottom: 1px solid #4b484f;
    user-select: none;
    cursor: move;
  }
  .window-title { font-size: 14px; font-weight: 600; color: #f2eef3; }
  .window-controls { height: 100%; display: flex; }
  .win-control {
    width: 43px;
    border: 0;
    color: #eee;
    background: transparent;
    cursor: pointer;
    font-size: 19px;
  }
  .win-control:hover { background: rgba(255,255,255,.12); }
  .win-close:hover { background: #d94343; color: white; }

  .files-toolbar {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 10px 12px;
    background: #302e34;
    border-bottom: 1px solid #46434a;
  }
  #files-up {
    width: 34px;
    height: 31px;
    border: 0;
    border-radius: 6px;
    background: #48454c;
    color: white;
    cursor: pointer;
    font-size: 20px;
  }
  #files-up:hover:not(:disabled) { background: #625e67; }
  #files-up:disabled { opacity: .4; cursor: default; }
  #files-path {
    flex: 1;
    min-width: 0;
    padding: 7px 10px;
    border-radius: 5px;
    color: #f4f1f5;
    background: #1f1e22;
    font-family: Consolas, monospace;
    font-size: 13px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  #files-list {
    flex: 1;
    overflow: auto;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(122px, 1fr));
    align-content: start;
    gap: 8px;
    padding: 15px;
    background: #252329;
  }
  .fs-item {
    min-height: 92px;
    border: 1px solid transparent;
    border-radius: 7px;
    padding: 10px 6px;
    color: #f4f1f5;
    background: transparent;
    cursor: pointer;
    text-align: center;
    overflow-wrap: anywhere;
  }
  .fs-item:hover, .fs-item.selected {
    border-color: #6c5592;
    background: rgba(120, 87, 177, .32);
  }
  .fs-glyph { display: block; font-size: 37px; line-height: 42px; }
  .fs-name { display: block; font-size: 13px; margin-top: 4px; }

  .notepad-body { display: flex; flex-direction: column; flex: 1; min-height: 0; background: #252329; }
  #tabs {
    display: flex;
    align-items: stretch;
    gap: 2px;
    overflow-x: auto;
    padding: 7px 7px 0;
    background: #302e34;
    min-height: 43px;
  }
  .tab {
    max-width: 160px;
    min-width: 100px;
    border: 0;
    border-radius: 7px 7px 0 0;
    padding: 9px 13px;
    color: #cfcad1;
    background: #454149;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: pointer;
    font-size: 13px;
  }
  .tab:hover { background: #56515a; }
  .tab.active { color: #fff; background: #252329; }
  #new-tab {
    width: 34px;
    height: 31px;
    flex: 0 0 34px;
    margin: 5px 7px 0 0;
    border: 0;
    border-radius: 6px;
    color: white;
    background: #514b55;
    cursor: pointer;
    font-size: 20px;
  }
  #new-tab:hover { background: #6a6370; }
  #editor {
    width: 100%;
    height: 100%;
    flex: 1;
    resize: none;
    border: 0;
    outline: 0;
    padding: 17px;
    color: #f5f2f5;
    background: #252329;
    font-family: Consolas, "Courier New", monospace;
    font-size: 14px;
    line-height: 1.55;
  }
  .statusline {
    padding: 5px 12px;
    color: #aaa4ac;
    background: #302e34;
    border-top: 1px solid #454149;
    font-size: 11px;
  }
</style>
</head>
<body>
<div id="desktop">
  <div class="topbar">
    <strong>Activities</strong>
    <span>Ubuntu Desktop</span>
    <span class="status">◉ &nbsp;⌁&nbsp; Aug 25 &nbsp;⏻</span>
  </div>

  <div class="desktop-icons" aria-hidden="true">
    <div class="desktop-icon"><span class="icon-art">⌂</span>Home</div>
    <div class="desktop-icon"><span class="icon-art">🗑</span>Trash</div>
  </div>

  <div id="files-window" class="window" role="dialog" aria-label="Files">
    <div class="titlebar">
      <span class="window-title">▣ &nbsp; Files</span>
      <div class="window-controls">
        <button class="win-control" aria-label="Minimize">−</button>
        <button class="win-control win-close" aria-label="Close Files">×</button>
      </div>
    </div>
    <div class="files-toolbar">
      <button id="files-up" aria-label="Go to parent directory">‹</button>
      <div id="files-path">/</div>
    </div>
    <div id="files-list" aria-label="Filesystem listing"></div>
  </div>

  <div id="notepad-window" class="window" role="dialog" aria-label="Notepad">
    <div class="titlebar">
      <span class="window-title">▤ &nbsp; Notepad</span>
      <div class="window-controls">
        <button class="win-control" aria-label="Minimize">−</button>
        <button class="win-control win-close" aria-label="Close Notepad">×</button>
      </div>
    </div>
    <div class="notepad-body">
      <div id="tabs" aria-label="Open notes"></div>
      <button id="new-tab" aria-label="Create new tab" title="New tab">+</button>
      <textarea id="editor" aria-label="Note editor" spellcheck="false"></textarea>
      <div class="statusline">Plain text · Saved automatically</div>
    </div>
  </div>

  <div id="taskbar">
    <button id="open-files" class="launcher" aria-label="Open Files">
      <span class="launcher-icon">🗀</span><small>Files</small>
    </button>
    <button id="open-notepad" class="launcher" aria-label="Open Notepad">
      <span class="launcher-icon">🗎</span><small>Notepad</small>
    </button>
  </div>
</div>

<script>
(() => {
  const filesystem = {
    "/": [
      { name: "bin", folder: true }, { name: "etc", folder: true },
      { name: "home", folder: true }, { name: "usr", folder: true },
      { name: "var", folder: true }, { name: "README.txt", folder: false }
    ],
    "/bin": [{ name: "bash", folder: false }, { name: "ls", folder: false }, { name: "python", folder: false }],
    "/etc": [{ name: "hostname", folder: false }, { name: "hosts", folder: false }, { name: "network", folder: true }],
    "/etc/network": [{ name: "interfaces", folder: false }],
    "/home": [{ name: "user", folder: true }],
    "/home/user": [
      { name: "Documents", folder: true }, { name: "Downloads", folder: true },
      { name: "Pictures", folder: true }, { name: "Desktop", folder: true },
      { name: "welcome.txt", folder: false }
    ],
    "/home/user/Documents": [{ name: "Project Notes.txt", folder: false }, { name: "Invoices", folder: true }],
    "/home/user/Documents/Invoices": [{ name: "August.pdf", folder: false }],
    "/home/user/Downloads": [{ name: "ubuntu-wallpaper.png", folder: false }, { name: "archive.zip", folder: false }],
    "/home/user/Pictures": [{ name: "Sunset.jpg", folder: false }, { name: "Vacation", folder: true }],
    "/home/user/Pictures/Vacation": [{ name: "Lake.png", folder: false }],
    "/home/user/Desktop": [{ name: "Shortcut.desktop", folder: false }],
    "/usr": [{ name: "bin", folder: true }, { name: "share", folder: true }],
    "/usr/bin": [{ name: "node", folder: false }, { name: "vim", folder: false }],
    "/usr/share": [{ name: "applications", folder: true }],
    "/usr/share/applications": [{ name: "notepad.desktop", folder: false }],
    "/var": [{ name: "log", folder: true }, { name: "tmp", folder: true }],
    "/var/log": [{ name: "syslog", folder: false }],
    "/var/tmp": []
  };

  const filesWindow = document.getElementById("files-window");
  const notepadWindow = document.getElementById("notepad-window");
  const pathElement = document.getElementById("files-path");
  const listElement = document.getElementById("files-list");
  const upButton = document.getElementById("files-up");
  let currentPath = "/";

  function showWindow(windowElement) {
    windowElement.classList.add("visible");
    windowElement.style.zIndex = String(Date.now());
  }

  function joinPath(parent, child) {
    return parent === "/" ? "/" + child : parent + "/" + child;
  }

  function renderFiles() {
    pathElement.textContent = currentPath;
    upButton.disabled = currentPath === "/";
    listElement.replaceChildren();
    (filesystem[currentPath] || []).forEach(entry => {
      const item = document.createElement("button");
      item.className = "fs-item";
      item.type = "button";
      item.title = entry.folder ? "Double-click to open " + entry.name : entry.name;
      item.innerHTML = '<span class="fs-glyph">' + (entry.folder ? "📁" : "📄") +
        '</span><span class="fs-name"></span>';
      item.querySelector(".fs-name").textContent = entry.name;
      item.addEventListener("click", () => {
        listElement.querySelectorAll(".fs-item.selected").forEach(el => el.classList.remove("selected"));
        item.classList.add("selected");
      });
      if (entry.folder) {
        item.addEventListener("dblclick", () => {
          currentPath = joinPath(currentPath, entry.name);
          renderFiles();
        });
      }
      listElement.appendChild(item);
    });
  }

  document.getElementById("open-files").addEventListener("click", () => {
    showWindow(filesWindow);
    renderFiles();
  });
  document.getElementById("open-notepad").addEventListener("click", () => showWindow(notepadWindow));
  document.querySelectorAll(".win-close").forEach(button => {
    button.addEventListener("click", event => event.target.closest(".window").classList.remove("visible"));
  });
  upButton.addEventListener("click", () => {
    if (currentPath === "/") return;
    const pieces = currentPath.split("/").filter(Boolean);
    pieces.pop();
    currentPath = pieces.length ? "/" + pieces.join("/") : "/";
    renderFiles();
  });

  const STORAGE_KEY = "ubuntu-notepad-tabs-v1";
  const tabsElement = document.getElementById("tabs");
  const editor = document.getElementById("editor");
  const newTabButton = document.getElementById("new-tab");
  let notebook;

  function defaultNotebook() {
    return {
      active: "tab-1",
      tabs: [{ id: "tab-1", title: "Note 1", content: "Welcome to Notepad.\n\nYour notes are saved automatically." }]
    };
  }

  function loadNotebook() {
    try {
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
      if (saved && Array.isArray(saved.tabs) && saved.tabs.length && saved.tabs.every(t => typeof t.id === "string")) {
        return saved;
      }
    } catch (error) {}
    return defaultNotebook();
  }

  function saveNotebook() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(notebook)); } catch (error) {}
  }

  function activeTab() {
    return notebook.tabs.find(tab => tab.id === notebook.active) || notebook.tabs[0];
  }

  function renderTabs() {
    if (!notebook.tabs.some(tab => tab.id === notebook.active)) notebook.active = notebook.tabs[0].id;
    tabsElement.replaceChildren();
    notebook.tabs.forEach((tab, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "tab" + (tab.id === notebook.active ? " active" : "");
      button.textContent = tab.title || ("Note " + (index + 1));
      button.title = button.textContent;
      button.addEventListener("click", () => {
        notebook.active = tab.id;
        renderTabs();
        saveNotebook();
        editor.focus();
      });
      tabsElement.appendChild(button);
    });
    editor.value = activeTab().content;
  }

  newTabButton.addEventListener("click", () => {
    const id = "tab-" + Date.now() + "-" + Math.random().toString(36).slice(2, 7);
    notebook.tabs.push({ id, title: "Note " + (notebook.tabs.length + 1), content: "" });
    notebook.active = id;
    renderTabs();
    saveNotebook();
    editor.focus();
  });

  editor.addEventListener("input", () => {
    activeTab().content = editor.value;
    saveNotebook();
  });

  [filesWindow, notepadWindow].forEach(win => {
    win.addEventListener("mousedown", () => { win.style.zIndex = String(Date.now()); });
  });

  notebook = loadNotebook();
  renderTabs();
  renderFiles();
})();
</script>
</body>
</html>
